const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

/** Copy the branded overlay image into the Android resources generated by CNG. */
module.exports = function withReturnOverlayLogo(config) {
  return withDangerousMod(config, [
    'android',
    async (androidConfig) => {
      const source = path.join(androidConfig.modRequest.projectRoot, 'assets', 'RCS-captains-logo.webp');
      const drawable = path.join(
        androidConfig.modRequest.platformProjectRoot,
        'app', 'src', 'main', 'res', 'drawable',
      );
      fs.mkdirSync(drawable, { recursive: true });
      fs.copyFileSync(source, path.join(drawable, 'rcs_captains_logo.webp'));
      return androidConfig;
    },
  ]);
};
